--
-- Table structure for table `attendance_records`
--

DROP TABLE IF EXISTS `attendance_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `attendance_records` (
  `attendance_id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `roster_id` int(11) NOT NULL,
  `class_date` date NOT NULL,
  `present` tinyint(4) DEFAULT 0,
  `attendance_source` enum('zoom','excel','manual','sqlite','imported') DEFAULT 'manual',
  `raw_name` varchar(200) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `first_join` datetime DEFAULT NULL,
  `last_leave` datetime DEFAULT NULL,
  `total_connections` int(11) DEFAULT 0,
  `total_minutes` decimal(10,2) DEFAULT 0.00,
  `status` varchar(50) DEFAULT NULL,
  `source_file` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`attendance_id`),
  UNIQUE KEY `uniq_attendance` (`student_id`,`roster_id`,`class_date`,`attendance_source`),
  KEY `roster_id` (`roster_id`),
  CONSTRAINT `attendance_records_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students_master` (`student_id`),
  CONSTRAINT `attendance_records_ibfk_2` FOREIGN KEY (`roster_id`) REFERENCES `rosters` (`roster_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

