--
-- Table structure for table `attendance_zoom`
--

DROP TABLE IF EXISTS `attendance_zoom`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `attendance_zoom` (
  `attendance_id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) DEFAULT NULL,
  `class_id` int(11) DEFAULT NULL,
  `raw_name` varchar(200) NOT NULL,
  `normalized_name` varchar(200) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `class_date` date NOT NULL,
  `first_join` datetime DEFAULT NULL,
  `last_leave` datetime DEFAULT NULL,
  `total_connections` int(11) DEFAULT 1,
  `total_minutes` decimal(10,2) DEFAULT 0.00,
  `source_file` varchar(255) DEFAULT NULL,
  `match_status` enum('matched','unmatched','manual_review') DEFAULT 'unmatched',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`attendance_id`),
  KEY `student_id` (`student_id`),
  KEY `class_id` (`class_id`),
  KEY `idx_zoom_date` (`class_date`),
  KEY `idx_zoom_raw_name` (`raw_name`),
  KEY `idx_zoom_student_date` (`student_id`,`class_date`),
  KEY `idx_zoom_normalized_date` (`normalized_name`,`class_date`),
  CONSTRAINT `attendance_zoom_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students_master` (`student_id`),
  CONSTRAINT `attendance_zoom_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

